"""PR #4 (v0.4) — keiko-engine ConLaw + URL-policy fix.

Two things:
  1. Replace ALL citation URLs in cards.json with Google search URLs.
     Justia's per-case page URL pattern doesn't work for every case
     (especially recent slip-ops where the U.S. Reports volume hasn't
     been published yet — 先輩 saw "Page not found" on a Justia link).
     Google search is guaranteed to surface the leading hit (SCOTUS
     opinion, Justia, Cornell LII, Wikipedia summary, all available).
  2. Add 50 NEW validated us-conlaw cards (cards 101-150) per the
     standing rule in CLAUDE.md §5.2.

Run from repo root:
    python scripts\\add_pr4_cards_and_google_urls.py
"""
from __future__ import annotations

import json
from pathlib import Path
from urllib.parse import quote_plus

CARDS_PATH = Path(__file__).resolve().parent.parent / "src" / "main" / "resources" / "subjects" / "us-conlaw" / "cards.json"


def google_url(label: str) -> str:
    """Build a Google search URL for a citation label. Guaranteed to
    resolve to *something* relevant — usually the SCOTUS opinion on
    supremecourt.gov, Justia, Cornell LII, or Wikipedia summary."""
    return f"https://www.google.com/search?q={quote_plus(label)}"


def cite_scotus(label: str) -> dict:
    return {"label": label, "url": google_url(label), "type": "scotus"}


def cite_circuit(label: str) -> dict:
    return {"label": label, "url": google_url(label), "type": "circuit"}


def cite_lr(label: str) -> dict:
    return {"label": label, "url": google_url(label), "type": "law-review"}


def card(id_, stem, choices_with_correct, explanation, citations,
         tags="us-conlaw", grammar_point="", difficulty=3):
    return {
        "id": id_, "kind": "grammar", "level": "",
        "stem": stem, "grammar_point": grammar_point,
        "choices": [{"text": t, "is_correct": c} for t, c in choices_with_correct],
        "translation_zh_tw": "", "translation_zh_cn": "", "translation_en": "",
        "explanation": explanation, "difficulty": difficulty, "tags": tags,
        "source": "claude-authored-may-2026",
        "provenance": "human_curated",
        "attribution": "Claude PR #4 (validated bank). Awaiting expert review.",
        "citations": citations,
    }


