def main():
    data = json.loads(CARDS_PATH.read_text(encoding="utf-8"))
    cards = data["cards"]

    # 1. Replace ALL existing citation URLs with Google search URLs.
    rewritten = 0
    for c in cards:
        cites = c.get("citations") or []
        for cite in cites:
            label = cite.get("label", "")
            if label:
                cite["url"] = google_url(label)
                rewritten += 1

    # 2. Append the 50 new cards (with Google search URLs from the start).
    existing_ids = {c["id"] for c in cards}
    added = 0
    for card_dict in NEW_CARDS:
        if card_dict["id"] not in existing_ids:
            cards.append(card_dict)
            added += 1

    # 3. Atomic write.
    tmp = CARDS_PATH.with_suffix(".json.tmp")
    tmp.write_text(json.dumps({"cards": cards}, ensure_ascii=False, indent=2) + "\n",
                   encoding="utf-8")
    tmp.replace(CARDS_PATH)

    print(f"Rewrote {rewritten} citation URLs to Google search format.")
    print(f"Added {added} new cards. Total cards now: {len(cards)}.")


if __name__ == "__main__":
    main()
